import{c as e,Q as o,j as s,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse(`{"title":"The Agent's Toolkit: \\"/\\"","description":"","frontmatter":{"url":"https://x.com/dongxi_nlp/status/2065713612384010332","title":"The Agent's Toolkit: \\"/\\"","author":"马东锡 NLP","archived":"2026-06-13T00:00:00.000Z","handle":"@dongxi_nlp","published":"2026-06-13T00:00:00.000Z","stats":"5 likes · 0 retweets · 5605 views","tags":["harness","slash-commands","agent-design","input-router","control-plane"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-06-13-@dongxi_nlp-010332.md","filePath":"research/tweets/2026-06-13-@dongxi_nlp-010332.md","lastUpdated":1785909234000}`),l={name:"research/tweets/2026-06-13-@dongxi_nlp-010332.md"};function i(n,t,r,d,c,p){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="the-agent-s-toolkit-—-dongxi-nlp" tabindex="-1">The Agent&#39;s Toolkit: &quot;/&quot; — @dongxi_nlp <a class="header-anchor" href="#the-agent-s-toolkit-—-dongxi-nlp" aria-label="Permalink to &quot;The Agent&#39;s Toolkit: &quot;/&quot; — @dongxi_nlp&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/dongxi_nlp/status/2065713612384010332" target="_blank" rel="noreferrer">https://x.com/dongxi_nlp/status/2065713612384010332</a><strong>作者</strong>：马东锡 NLP（@dongxi_nlp） <strong>發布日期</strong>：2026-06-13 <strong>收錄日期</strong>：2026-06-13 <strong>類型</strong>：Twitter Article（Harness 系列之 4） <strong>統計</strong>：5 likes · 0 retweets · 5605 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Harness 系列文章之 4，斜杠让 coding agent 超出单纯 prompt box。</p><blockquote><p>不是所有的 input，都可以成为 prompt。</p></blockquote><p>每个 coding-agent UI 都从一个简单想法开始： 输入请求，发给 model，拿回结果。这是 prompt-box 视角下的 agent。 普通请求很适合这样处理： [圖 1] 但产品级的 coding agent 还有另一类 input：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/status、/tools、/reset、/goal pause、/audit</span></span></code></pre></div><p>这些 input 不该交给 model 当普通请求理解。 它们是用户用来控制 agent runtime 的 tools。</p><blockquote><p>Do not send control-plane intent to the model as ordinary chat. [圖 2]</p></blockquote><h2 id="the-naive-prompt-box" tabindex="-1">The Naive Prompt Box <a class="header-anchor" href="#the-naive-prompt-box" aria-label="Permalink to &quot;The Naive Prompt Box&quot;">​</a></h2><p>tiny agent 往往把所有 text 都用同一条路径处理： [圖 3] 这样很简单，也会让产品陷入困境。</p><ul><li>用户输入 /status，model 可能编一个 status</li><li>用户输入 /reset，model 可能讨论 reset，却没有清理 session state</li><li>用户输入 /goal pause，model 可能把它当成当前 task 里的 instruction</li><li>用户把 /status 打成 /statsu，model 可能试图帮忙猜，而非返回 command help 问题发生在 model quality 之前。harness 没有正确 route input。</li></ul><h2 id="slash-commands-are-user-tools" tabindex="-1">Slash Commands Are User Tools <a class="header-anchor" href="#slash-commands-are-user-tools" aria-label="Permalink to &quot;Slash Commands Are User Tools&quot;">​</a></h2><p>Article 03 说，model tools 是 contracts。 slash commands 属于另一类 tool，它们属于用户和 harness。 它们可以在 model call 出现之前 inspect，steer，reset，pause，diagnose，configure runtime。 一个简单的 command families 如下： [圖 4]</p><ul><li>有些 command 产生 local output</li><li>有些 command 修改 session state</li><li>有些 command 展示 harness metadata</li><li>有些 command 为下一轮 model turn 准备 context 它们都需要在 prompt construction 之前被 route。</li></ul><p>此时的关键词已经出来了，那就是</p><blockquote><p>Input Router</p></blockquote><h2 id="the-input-router" tabindex="-1">The Input Router <a class="header-anchor" href="#the-input-router" aria-label="Permalink to &quot;The Input Router&quot;">​</a></h2><p>有用的 coding-agent harness 有两个 parser boundary。 第一层处理 user input，后一层处理 model output。 input router 应该判断： [圖 5] 只有最后一条路径应该进入 agent.ask() Prompt box 不再是唯一入口，Harness 拥有自己的 control surface。</p><blockquote><p>Not Every Input Becomes A prompt [圖 6]</p></blockquote><h2 id="the-special-case-goal" tabindex="-1">The Special Case: /goal <a class="header-anchor" href="#the-special-case-goal" aria-label="Permalink to &quot;The Special Case: /goal&quot;">​</a></h2><p>/goal 是最有意思的 slash command，因为它夹在 user control 和 model work 之间。</p><blockquote><p>goal 是显式 session state [圖 7] user-facing command 控制 lifecycle： /goal <code>&lt;objective&gt;</code> / /goal pause / /goal resume / /goal complete / /goal clear</p></blockquote><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">objective</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal pause </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal resume </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal complete </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">goal clear</span></span></code></pre></div><p>Model 可以在 prompt 里看到 goal context。 但 model 不能随意 create，pause，resume，clear goals。</p><blockquote><p>get_goal() / update_goal(status=&quot;complete&quot;) goal 可以引导 model，用户仍然拥有 control state。 completion 应该依赖 evidence，而非 model 觉得已经完成。</p></blockquote><h2 id="diagnostics-should-stay-local" tabindex="-1">Diagnostics Should Stay Local <a class="header-anchor" href="#diagnostics-should-stay-local" aria-label="Permalink to &quot;Diagnostics Should Stay Local&quot;">​</a></h2><p>有些 command 应该直接 inspect harness。 /audit 和 /doctor 是很好的例子。 它们不应该问 model：</p><blockquote><p>does my session look healthy? 它们应该检查 deterministic state，例如使用 /audit 或者 /doctor [圖 8] 第一步检查应该在 local 完成。 diagnostics 作为 local command 时，harness 可以报告真实 invariants。</p></blockquote><h2 id="why-this-changes-the-product" tabindex="-1">Why This Changes The Product <a class="header-anchor" href="#why-this-changes-the-product" aria-label="Permalink to &quot;Why This Changes The Product&quot;">​</a></h2><p>一旦有 slash commands，用户拥有的不只是 prompt box。 用户可以问：</p><ul><li>当前 workspace 是哪里？</li><li>有哪些 tools 可用？</li><li>当前 active goal 是什么？</li><li>哪些 state 会进入下一轮？</li><li>上次 edit 之后发生了什么？</li><li>harness 内部是否一致？</li><li>这个 session 应该 reset、pause、resume，还是 compact？ 这些是 runtime questions，它们需要 runtime answers。 slash 后面的 text 属于 harness，而非 model。 所以 coding-agent harness 应该有： [圖 9] Prompt box 是用户请求工作的地方。 Slash 是用户控制 worker 的地方。</li></ul><p>这就是 agent toolkit 从 / 开始的原因。</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Slash commands 是 user→harness 的 control plane（非 prompt），coding agent 應有 input router 在 prompt construction 之前 route，diagnostics/state/lifecycle 必須走 deterministic local 路徑而非問 model。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li><strong>不是所有 input 都是 prompt</strong>：<code>/status</code>、<code>/reset</code>、<code>/goal pause</code>、<code>/audit</code> 屬於 runtime control，交給 model 處理會出現編造 status、不清 session state、把 control 當任務 instruction 等 4 類失敗。</li><li><strong>兩個 parser boundary</strong>：harness 需要 input router（user input）+ output parser（model output）兩層；只有最後一條路徑進 <code>agent.ask()</code>。</li><li><strong>/goal 是顯式 session state</strong>：user 控 lifecycle（pause/resume/complete/clear）；model 只能 <code>get_goal()</code> / <code>update_goal(status=...)</code> 受限操作；completion 依 evidence 不靠 model 自評。</li><li><strong>Diagnostics 必須 local</strong>：<code>/audit</code>、<code>/doctor</code> 應檢查 deterministic state，不該問 model「我看起來健康嗎」——和 The Loop TEST 階段「unverified_success 閘門必由主對話親跑」一脈相承。</li><li><strong>Slash 後屬 harness，非 model</strong>：產品邊界從 prompt box 升級成 control surface，這是 coding agent 從玩具走向產品的關鍵切分。</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>Harness 系列第 4 篇（連續主題：tools→prompts→contracts→slash）</li><li>提及 command families：產生 local output / 修改 session state / 展示 harness metadata / 為下輪 prepare context</li><li>反例：<code>/statsu</code> typo 時 model 不該幫忙猜，而要回傳 command help</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li><strong>概念導向、缺實作對照</strong>：9 張圖佔位多為 placeholder，無 router schema/code snippet 對比，論述屬 manifesto 級別；workspace 若已實作 slash skill 路由，這篇主要是事後概念背書。</li><li><strong>與 The Loop 高度重疊</strong>：Workspace 的 <code>LLM 判斷 vs deterministic 決定</code> 跨切紀律（core.md）已涵蓋本文 90% 觀點；<code>/audit</code> local check 對應 <code>unverified_success</code> 閘門。</li><li><strong>/goal 是亮點</strong>：把 goal 拉成 first-class session state（非 prompt 內字串）是相對較新的設計分層，可考慮對應到 <code>claude-progress.json</code> overnight 機制延伸。</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>6/10</td><td>Workspace 已用 100+ skills/commands；input router 概念可用於下次 skill router 設計 review，但無新增 hook 需求。</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>Control plane vs prompt 分層是業界共識；<code>/goal</code> 作 session state、<code>/audit</code> local-only 切分屬中等獨到。</td></tr><tr><td>C. 證據品質 (20%)</td><td>4/10</td><td>純論述，無 benchmark/code/case study；9 張圖多為流程示意，無真實 router 實作對照。</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>提及 two parser boundary、prompt construction 前置 route、deterministic invariants，但每點點到為止。</td></tr><tr><td>E. 泛化性 (15%)</td><td>8/10</td><td>適用所有 coding agent harness（Claude Code / Cursor / Aider 等）。</td></tr><tr><td><strong>加權總分</strong></td><td><strong>5.75/10</strong></td><td>6×0.3 + 6×0.2 + 4×0.2 + 5×0.15 + 8×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip — 概念與 The Loop / harness-meta SKILL 高度重疊，已實作。 <strong>理由</strong>：Workspace 既有 <code>unverified_success</code> 閘門 + slash skill router 已體現本文論點，無新增 hook/skill 需求；保留歸檔作為 The Loop 跨切紀律的外部背書。</p>`,47)])])}const g=e(l,[["render",i]]);export{u as __pageData,g as default};
